    function initAntibioticResistanceLab() {
      const canvas = document.getElementById('antibiotic-resistance-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-antibiotic-resistance');
      const obs = document.getElementById('antibiotic-resistance-obs');

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const isFull = sel.value === 'full-course';
        const cols = 8, rows = 3;
        const startX = W / 2 - (cols * 40) / 2 + 20, startY = 80;

        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const x = startX + c * 40, y = startY + r * 40;
            const killed = isFull || (r < 2);
            ctx.fillStyle = killed ? 'rgba(148,163,184,0.25)' : '#ef4444';
            ctx.beginPath(); ctx.arc(x, y, 12, 0, Math.PI * 2); ctx.fill();
            if (killed) {
              ctx.strokeStyle = cssVar('--text-muted'); ctx.lineWidth = 1.5;
              ctx.beginPath(); ctx.moveTo(x - 8, y - 8); ctx.lineTo(x + 8, y + 8); ctx.moveTo(x + 8, y - 8); ctx.lineTo(x - 8, y + 8); ctx.stroke();
            }
          }
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = isFull ? '#22c55e' : '#ef4444'; ctx.textAlign = 'center';
        ctx.fillText(isFull ? 'All bacteria killed' : 'Resistant bacteria survive & multiply', W / 2, 235);

        obs.innerHTML = isFull
          ? `<strong>✓ Full course completed:</strong> All targeted bacteria — including partially-resistant ones — are killed, preventing resistance from developing.`
          : `<strong>✗ Incomplete dose:</strong> Weaker bacteria die quickly, but stronger, partially-resistant bacteria survive the shortened treatment and multiply — spreading antibiotic resistance.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initCompassDeflectionLab() {
      const canvas = document.getElementById('compass-deflection-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-compass-deflection');
      const obs = document.getElementById('compass-deflection-obs');

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const state = sel.value;
        const cx = W / 2, cy = 150;

        ctx.strokeStyle = state === 'off' ? cssVar('--border-color') : '#f59e0b'; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.moveTo(cx - 150, cy - 70); ctx.lineTo(cx + 150, cy - 70); ctx.stroke();
        ctx.font = '11px system-ui'; ctx.fillStyle = cssVar('--text-muted'); ctx.textAlign = 'center';
        ctx.fillText('Wire (above compass)', cx, cy - 85);

        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(cx, cy, 55, 0, Math.PI * 2); ctx.stroke();

        let angle = -Math.PI / 2;
        if (state === 'on-forward') angle -= 0.6;
        else if (state === 'on-reverse') angle += 0.6;

        ctx.save(); ctx.translate(cx, cy); ctx.rotate(angle);
        ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.moveTo(0, -45); ctx.lineTo(-8, 0); ctx.lineTo(8, 0); ctx.closePath(); ctx.fill();
        ctx.fillStyle = cssVar('--text-normal'); ctx.beginPath(); ctx.moveTo(0, 45); ctx.lineTo(-8, 0); ctx.lineTo(8, 0); ctx.closePath(); ctx.fill();
        ctx.restore();

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(state === 'off' ? 'Switch OFF — No Current' : 'Switch ON — Current Flowing', W / 2, 245);

        obs.innerHTML = state === 'off'
          ? `<strong>No deflection:</strong> With the switch off, no current flows, so there is no magnetic field — the compass needle points normally (north).`
          : `<strong>Needle deflects ${state === 'on-forward' ? 'one way' : 'the opposite way'}:</strong> Current flowing through the wire creates a magnetic field that deflects the needle. Reversing the current's direction reverses the direction of deflection.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initElectromagnetStrengthLab() {
      const canvas = document.getElementById('electromagnet-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-electromagnet');
      const obs = document.getElementById('electromagnet-obs');
      const SETUPS = {
        '1cell-nonail': { strength: 1, clips: 0, desc: 'A coil alone (no iron core) with 1 cell produces only a weak magnetic field — too weak to attract clips.' },
        '1cell-nail': { strength: 2, clips: 2, desc: 'Adding an iron nail as a core makes the coil a much stronger magnet, now able to attract a few clips.' },
        '2cell-nail': { strength: 3, clips: 4, desc: 'Using 2 cells increases the current, creating an even stronger magnetic field and attracting more clips.' },
        '2cell-moreturns': { strength: 4, clips: 6, desc: 'Combining 2 cells with more coil turns gives the strongest magnetic field, attracting the most clips.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const s = SETUPS[sel.value];
        const cx = W / 2;

        const barMaxW = 400, barH = 30, barX = cx - barMaxW / 2, barY = 80;
        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 1.5;
        ctx.strokeRect(barX, barY, barMaxW, barH);
        ctx.fillStyle = cssVar('--accent-color');
        ctx.fillRect(barX, barY, (s.strength / 4) * barMaxW, barH);
        ctx.font = 'bold 13px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(`Relative Magnetic Strength: ${s.strength}/4`, cx, barY - 12);

        for (let i = 0; i < s.clips; i++) {
          const x = cx - (s.clips - 1) * 15 + i * 30;
          ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 3;
          ctx.beginPath(); ctx.arc(x, 170, 10, 0.3, Math.PI * 1.7); ctx.stroke();
        }
        ctx.font = '12px system-ui'; ctx.fillStyle = cssVar('--text-muted'); ctx.textAlign = 'center';
        ctx.fillText(s.clips === 0 ? 'No clips attracted' : `${s.clips} clips attracted`, cx, 210);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${s.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initHeatingEffectLab() {
      const canvas = document.getElementById('heating-effect-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-heating-effect');
      const obs = document.getElementById('heating-effect-obs');
      const SETUPS = {
        'copper-1cell': { level: 1, color: '#94a3b8', desc: 'Copper wire has low resistance, so with 1 cell it stays close to room temperature — barely warm.' },
        'nichrome-1cell': { level: 2, color: '#f59e0b', desc: 'Nichrome wire has much higher resistance than copper, so with 1 cell it becomes noticeably warm.' },
        'nichrome-2cell': { level: 3, color: '#ef4444', desc: 'Nichrome wire with 2 cells carries more current, generating even more heat — the wire becomes distinctly hot.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const s = SETUPS[sel.value];
        const cx = W / 2, cy = 140;

        ctx.strokeStyle = s.color; ctx.lineWidth = 6;
        ctx.beginPath(); ctx.moveTo(cx - 150, cy); ctx.lineTo(cx + 150, cy); ctx.stroke();

        const thermX = cx + 200, thermTop = 60, thermBottom = 220;
        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(thermX, thermTop); ctx.lineTo(thermX, thermBottom); ctx.stroke();
        const fillH = (s.level / 3) * (thermBottom - thermTop);
        ctx.strokeStyle = s.color; ctx.lineWidth = 6; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(thermX, thermBottom); ctx.lineTo(thermX, thermBottom - fillH); ctx.stroke();
        ctx.lineCap = 'butt';

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);
        ctx.font = '12px system-ui'; ctx.fillStyle = s.color;
        const labels = ['', 'Slightly warm', 'Warm', 'Hot'];
        ctx.fillText(labels[s.level], cx, cy + 40);

        obs.innerHTML = `<strong>${labels[s.level]}:</strong> ${s.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initBatteryTypesLab() {
      const canvas = document.getElementById('battery-types-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-battery-types');
      const obs = document.getElementById('battery-types-obs');
      const INFO = {
        voltaic: { desc: 'Two different metal electrodes (e.g., copper and iron) dipped in a liquid electrolyte (e.g., lemon juice). Chemical reaction generates current; the cell eventually "dies" as chemicals are used up.' },
        dry: { desc: 'Zinc container (negative terminal) surrounds a paste-like electrolyte, with a central carbon rod and metal cap (positive terminal). Single-use — must be disposed of once used up.' },
        rechargeable: { desc: 'Can be charged and reused many times, unlike single-use cells. Lithium-ion (Li-ion) is the most common type today, found in phones, laptops, and electric vehicles.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const type = sel.value;
        const cx = W / 2, cy = 140;

        if (type === 'voltaic') {
          ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
          ctx.strokeRect(cx - 70, cy - 60, 140, 100);
          ctx.fillStyle = 'rgba(59,130,246,0.15)'; ctx.fillRect(cx - 68, cy - 20, 136, 58);
          ctx.fillStyle = '#f59e0b'; ctx.fillRect(cx - 45, cy - 70, 8, 90);
          ctx.fillStyle = '#94a3b8'; ctx.fillRect(cx + 37, cy - 70, 8, 90);
          ctx.font = '10px system-ui'; ctx.fillStyle = cssVar('--text-muted'); ctx.textAlign = 'center';
          ctx.fillText('Electrode 1 (Cu)', cx - 41, cy - 78);
          ctx.fillText('Electrode 2 (Fe)', cx + 41, cy - 78);
          ctx.fillText('Electrolyte (liquid)', cx, cy + 55);
        } else if (type === 'dry') {
          ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 3;
          ctx.strokeRect(cx - 40, cy - 70, 80, 130);
          ctx.fillStyle = 'rgba(148,163,184,0.15)'; ctx.fillRect(cx - 38, cy - 68, 76, 126);
          ctx.fillStyle = '#1f2937'; ctx.fillRect(cx - 6, cy - 80, 12, 130);
          ctx.fillStyle = '#f59e0b'; ctx.fillRect(cx - 10, cy - 90, 20, 12);
          ctx.font = '10px system-ui'; ctx.fillStyle = cssVar('--text-muted'); ctx.textAlign = 'center';
          ctx.fillText('Metal cap (+)', cx, cy - 98);
          ctx.fillText('Carbon rod', cx + 30, cy - 20);
          ctx.fillText('Zinc container (−)', cx, cy + 75);
        } else {
          ctx.fillStyle = cssVar('--accent-color'); ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
          ctx.beginPath(); ctx.roundRect(cx - 60, cy - 40, 120, 80, 10); ctx.fill(); ctx.stroke();
          ctx.font = 'bold 12px system-ui'; ctx.fillStyle = '#0b1220'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
          ctx.fillText('Li-ion', cx, cy);
          ctx.textBaseline = 'alphabetic';
          ctx.font = '10px system-ui'; ctx.fillStyle = cssVar('--text-muted');
          ctx.fillText('Rechargeable — 100s of cycles', cx, cy + 60);
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${INFO[type].desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initForceEffectLab() {
      const canvas = document.getElementById('force-effect-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-force-effect');
      const obs = document.getElementById('force-effect-obs');
      const EFFECTS = {
        'push-rest': { flags: ['start'], desc: 'The box was at rest and starts moving — the force makes it move from rest.' },
        'hit-ball': { flags: ['direction'], desc: 'The ball was already moving; hitting it with a bat changes its direction of motion.' },
        'press-balloon': { flags: ['shape'], desc: 'The balloon’s shape changes as it is pressed inward — a change in shape.' },
        'brake-bicycle': { flags: ['speed'], desc: 'The moving bicycle slows down — the brake force changes (decreases) its speed.' }
      };
      const ALL = [['start', 'Starts Motion'], ['speed', 'Changes Speed'], ['direction', 'Changes Direction'], ['shape', 'Changes Shape']];

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const e = EFFECTS[sel.value];

        let y = 70;
        ALL.forEach(([key, label]) => {
          const active = e.flags.includes(key);
          ctx.fillStyle = active ? 'rgba(34,197,94,0.2)' : 'rgba(148,163,184,0.08)';
          ctx.fillRect(120, y - 22, 360, 36);
          ctx.strokeStyle = active ? '#22c55e' : cssVar('--border-color'); ctx.lineWidth = active ? 2.5 : 1;
          ctx.strokeRect(120, y - 22, 360, 36);
          ctx.font = active ? 'bold 14px system-ui' : '13px system-ui'; ctx.fillStyle = active ? '#22c55e' : cssVar('--text-muted'); ctx.textAlign = 'left';
          ctx.fillText((active ? '✓ ' : '') + label, 135, y + 3);
          y += 50;
        });

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 35);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${e.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initFrictionSurfaceLab() {
      const canvas = document.getElementById('friction-surface-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-friction-surface');
      const obs = document.getElementById('friction-surface-obs');
      const SURFACES = {
        glass: { dist: 0.95, desc: 'Very smooth — minimal irregularities mean very low friction, so the object slides far before stopping.' },
        tile: { dist: 0.8, desc: 'Smooth — low friction lets the object slide a good distance.' },
        wood: { dist: 0.55, desc: 'Medium roughness — moderate friction brings the object to a stop sooner.' },
        cloth: { dist: 0.3, desc: 'Rough — high friction from fabric fibers stops the object quickly.' },
        sand: { dist: 0.12, desc: 'Very rough — loose grains create very high friction, stopping the object almost immediately.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const s = SURFACES[sel.value];
        const trackY = 180, trackX = 60, trackW = 480;

        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(trackX, trackY); ctx.lineTo(trackX + trackW, trackY); ctx.stroke();

        const stopX = trackX + trackW * s.dist;
        ctx.strokeStyle = cssVar('--accent-color'); ctx.lineWidth = 6;
        ctx.beginPath(); ctx.moveTo(trackX, trackY); ctx.lineTo(stopX, trackY); ctx.stroke();

        ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(stopX, trackY - 12, 10, 0, Math.PI * 2); ctx.fill();

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 35);
        ctx.font = '12px system-ui'; ctx.fillStyle = cssVar('--text-muted');
        ctx.fillText('Object slides here → stops due to friction', W / 2, 220);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${s.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initNoncontactForceLab() {
      const canvas = document.getElementById('noncontact-force-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-noncontact-force');
      const obs = document.getElementById('noncontact-force-obs');
      const SCENARIOS = {
        'magnet-like': { repel: true, labels: ['N', 'N'], color: '#3b82f6', desc: 'Like poles (North-North) repel — the magnets push apart, letting one float above the other.' },
        'magnet-unlike': { repel: false, labels: ['N', 'S'], color: '#3b82f6', desc: 'Unlike poles (North-South) attract — the magnets pull together.' },
        'charge-like': { repel: true, labels: ['+', '+'], color: '#ef4444', desc: 'Both balloons carry similar (like) charges from rubbing with the same wool — like charges repel.' },
        'charge-unlike': { repel: false, labels: ['+', '−'], color: '#ef4444', desc: 'The balloon and wool cloth carry opposite (unlike) charges — unlike charges attract.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const s = SCENARIOS[sel.value];
        const cy = 140;
        const gap = s.repel ? 160 : 60;
        const x1 = W / 2 - gap / 2, x2 = W / 2 + gap / 2;

        [x1, x2].forEach((x, i) => {
          ctx.fillStyle = s.color; ctx.beginPath(); ctx.arc(x, cy, 35, 0, Math.PI * 2); ctx.fill();
          ctx.font = 'bold 18px system-ui'; ctx.fillStyle = 'white'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
          ctx.fillText(s.labels[i], x, cy); ctx.textBaseline = 'alphabetic';
        });

        ctx.strokeStyle = cssVar('--text-normal'); ctx.lineWidth = 2.5;
        const midX = W / 2;
        if (s.repel) {
          ctx.beginPath(); ctx.moveTo(midX - 15, cy); ctx.lineTo(midX - 45, cy); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(midX - 45, cy); ctx.lineTo(midX - 35, cy - 6); ctx.lineTo(midX - 35, cy + 6); ctx.closePath(); ctx.fill();
          ctx.beginPath(); ctx.moveTo(midX + 15, cy); ctx.lineTo(midX + 45, cy); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(midX + 45, cy); ctx.lineTo(midX + 35, cy - 6); ctx.lineTo(midX + 35, cy + 6); ctx.closePath(); ctx.fill();
        } else {
          ctx.beginPath(); ctx.moveTo(x1 + 45, cy); ctx.lineTo(x1 + 20, cy); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(x1 + 20, cy); ctx.lineTo(x1 + 30, cy - 6); ctx.lineTo(x1 + 30, cy + 6); ctx.closePath(); ctx.fill();
          ctx.beginPath(); ctx.moveTo(x2 - 45, cy); ctx.lineTo(x2 - 20, cy); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(x2 - 20, cy); ctx.lineTo(x2 - 30, cy - 6); ctx.lineTo(x2 - 30, cy + 6); ctx.closePath(); ctx.fill();
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = s.repel ? '#ef4444' : '#22c55e'; ctx.textAlign = 'center';
        ctx.fillText(s.repel ? 'REPEL (push apart)' : 'ATTRACT (pull together)', W / 2, 230);

        obs.innerHTML = `<strong>${s.repel ? 'Repel' : 'Attract'}:</strong> ${s.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initWeightOnPlanetsLab() {
      const canvas = document.getElementById('weight-planets-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-weight-planets');
      const obs = document.getElementById('weight-planets-obs');
      const WEIGHTS = { earth: 10, moon: 1.6, mars: 3.8, venus: 9, jupiter: 25.4 };
      const NAMES = { earth: 'Earth', moon: 'Moon', mars: 'Mars', venus: 'Venus', jupiter: 'Jupiter' };
      const MAXW = 26;

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const key = sel.value;
        const w = WEIGHTS[key];

        const barX = 200, barY = 60, barMaxH = 160, barW = 80;
        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 1.5;
        ctx.strokeRect(barX, barY, barW, barMaxH);
        const fillH = (w / MAXW) * barMaxH;
        ctx.fillStyle = cssVar('--accent-color');
        ctx.fillRect(barX, barY + barMaxH - fillH, barW, fillH);

        ctx.font = 'bold 16px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(`${NAMES[key]}: ${w} N`, barX + barW / 2, barY - 15);
        ctx.font = '12px system-ui'; ctx.fillStyle = cssVar('--text-muted');
        ctx.fillText('for a fixed 1 kg mass', barX + barW / 2, barY + barMaxH + 25);

        obs.innerHTML = `<strong>On ${NAMES[key]}, a 1 kg mass weighs ${w} N.</strong> The mass never changes (always 1 kg), but the weight changes because each location has a different gravitational pull.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initPressureCalcLab() {
      const canvas = document.getElementById('pressure-calc-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-pressure-calc');
      const obs = document.getElementById('pressure-calc-obs');
      const FORCE = 100;

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const area = parseFloat(sel.value);
        const pressure = FORCE / area;
        const sqSize = 30 + Math.sqrt(area) * 60;
        const cx = W / 2, cy = 150;

        ctx.fillStyle = 'rgba(16,185,129,0.2)'; ctx.strokeStyle = cssVar('--accent-color'); ctx.lineWidth = 2.5;
        ctx.fillRect(cx - sqSize / 2, cy - sqSize / 2, sqSize, sqSize);
        ctx.strokeRect(cx - sqSize / 2, cy - sqSize / 2, sqSize, sqSize);

        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(cx, cy - sqSize / 2 - 40); ctx.lineTo(cx, cy - sqSize / 2 - 5); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(cx, cy - sqSize / 2 - 5); ctx.lineTo(cx - 7, cy - sqSize / 2 - 18); ctx.lineTo(cx + 7, cy - sqSize / 2 - 18); ctx.closePath(); ctx.fill();
        ctx.font = '12px system-ui'; ctx.fillStyle = '#ef4444'; ctx.textAlign = 'center';
        ctx.fillText('100 N', cx, cy - sqSize / 2 - 48);

        ctx.font = 'bold 15px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(`Area = ${area} m²`, W / 2, 250);
        ctx.font = 'bold 16px system-ui'; ctx.fillStyle = '#22c55e';
        ctx.fillText(`Pressure = ${pressure} N/m²`, W / 2, 30);

        obs.innerHTML = `<strong>Force = 100 N, Area = ${area} m²:</strong> Pressure = 100 / ${area} = <strong style="color:#22c55e;">${pressure} N/m²</strong>. Smaller area with the same force always produces higher pressure.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initLiquidPressureLab() {
      const canvas = document.getElementById('liquid-pressure-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-liquid-pressure');
      const obs = document.getElementById('liquid-pressure-obs');
      const LEVELS = { low: 0.35, medium: 0.6, high: 0.9 };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const frac = LEVELS[sel.value];
        const pipeX = W / 2, pipeTop = 40, pipeBottom = 200, pipeW = 50;

        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
        ctx.strokeRect(pipeX - pipeW / 2, pipeTop, pipeW, pipeBottom - pipeTop);
        const waterH = (pipeBottom - pipeTop) * frac;
        ctx.fillStyle = 'rgba(59,130,246,0.4)';
        ctx.fillRect(pipeX - pipeW / 2, pipeBottom - waterH, pipeW, waterH);

        const bulgeR = 15 + frac * 35;
        ctx.fillStyle = '#ef4444';
        ctx.beginPath(); ctx.arc(pipeX, pipeBottom + bulgeR * 0.6, bulgeR, 0, Math.PI * 2); ctx.fill();

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 25);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> A ${sel.value === 'low' ? 'small' : sel.value === 'medium' ? 'moderate' : 'large'} water column height produces a ${sel.value === 'low' ? 'small' : sel.value === 'medium' ? 'moderate' : 'large'} bulge — confirming pressure increases with column height, not pipe width.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initWindFormationLab() {
      const canvas = document.getElementById('wind-formation-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-wind-formation');
      const obs = document.getElementById('wind-formation-obs');

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const isDay = sel.value === 'day';
        const landX = 0, landW = W * 0.4, seaX = W * 0.4, seaW = W * 0.6;
        const groundY = 180;

        ctx.fillStyle = '#78350f'; ctx.fillRect(landX, groundY, landW, 40);
        ctx.fillStyle = '#1e40af'; ctx.fillRect(seaX, groundY, seaW, 40);
        ctx.font = '12px system-ui'; ctx.fillStyle = 'white'; ctx.textAlign = 'center';
        ctx.fillText('LAND', landW / 2, groundY + 25);
        ctx.fillText('SEA', seaX + seaW / 2, groundY + 25);

        const arrowY = 130;
        ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3;
        if (isDay) {
          ctx.beginPath(); ctx.moveTo(seaX + 40, arrowY); ctx.lineTo(landW - 20, arrowY); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(landW - 20, arrowY); ctx.lineTo(landW - 35, arrowY - 8); ctx.lineTo(landW - 35, arrowY + 8); ctx.closePath(); ctx.fill();
        } else {
          ctx.beginPath(); ctx.moveTo(landW - 20, arrowY); ctx.lineTo(seaX + 40, arrowY); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(seaX + 40, arrowY); ctx.lineTo(seaX + 55, arrowY - 8); ctx.lineTo(seaX + 55, arrowY + 8); ctx.closePath(); ctx.fill();
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(isDay ? 'Sea Breeze (sea → land)' : 'Land Breeze (land → sea)', W / 2, 30);

        obs.innerHTML = isDay
          ? `<strong>Daytime — Sea Breeze:</strong> Land heats faster than the sea, so warm air over land rises, creating low pressure. Higher-pressure air from the sea flows in to replace it.`
          : `<strong>Nighttime — Land Breeze:</strong> The sea stays warmer than the land at night, so warm air over the sea rises, creating low pressure there. Higher-pressure air from the land flows out to sea.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initCyclonePressureLab() {
      const canvas = document.getElementById('cyclone-pressure-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-cyclone-pressure');
      const obs = document.getElementById('cyclone-pressure-obs');
      const RINGS = [
        { key: 'eye', r: 20, mb: 994, wind: 'Calm' },
        { key: 'near', r: 55, mb: 996, wind: 'Very strong winds' },
        { key: 'mid', r: 90, mb: 998, wind: 'Strong winds' },
        { key: 'far', r: 125, mb: 1008, wind: 'Light winds' }
      ];

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const cx = W / 2, cy = 150;
        const selected = sel.value;

        [...RINGS].reverse().forEach(ring => {
          ctx.beginPath(); ctx.arc(cx, cy, ring.r, 0, Math.PI * 2);
          ctx.fillStyle = ring.key === selected ? 'rgba(239,68,68,0.35)' : 'rgba(148,163,184,0.12)';
          ctx.fill();
          ctx.strokeStyle = ring.key === selected ? '#ef4444' : cssVar('--border-color'); ctx.lineWidth = ring.key === selected ? 2.5 : 1;
          ctx.stroke();
        });

        const sr = RINGS.find(r => r.key === selected);
        ctx.font = 'bold 13px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(`${sr.mb} mb`, cx, cy + 4);

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal');
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}: ${sr.mb} mb.</strong> Wind conditions: ${sr.wind}. Pressure rises steadily from 994 mb at the eye to 1008 mb at the outer edge — this pressure difference drives the cyclone's winds.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initParticleBreakdownLab() {
      const canvas = document.getElementById('particle-breakdown-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-particle-breakdown');
      const obs = document.getElementById('particle-breakdown-obs');
      const STAGES = {
        whole: { desc: 'A whole stick of chalk — one continuous-looking piece.' },
        broken: { desc: 'Broken by hand into several pieces — still clearly chalk, just smaller.' },
        powder: { desc: 'Ground with mortar and pestle into a fine powder — every speck is still chalk (a physical change).' },
        particles: { desc: 'Imagining grinding continued forever, we reach constituent particles — the smallest units chalk is made of, too small to see even with a magnifying glass.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const stage = sel.value;
        const cx = W / 2, cy = 150;
        ctx.fillStyle = '#e5e7eb';

        if (stage === 'whole') {
          ctx.fillRect(cx - 60, cy - 15, 120, 30);
        } else if (stage === 'broken') {
          [[-70, 0], [-10, 5], [50, -8]].forEach(([dx, dy]) => ctx.fillRect(cx + dx, cy + dy - 10, 35, 20));
        } else if (stage === 'powder') {
          for (let i = 0; i < 60; i++) {
            const x = cx + (Math.random() - 0.5) * 200, y = cy + (Math.random() - 0.5) * 80;
            ctx.beginPath(); ctx.arc(x, y, 2.5, 0, Math.PI * 2); ctx.fill();
          }
        } else {
          for (let i = 0; i < 150; i++) {
            const x = cx + (Math.random() - 0.5) * 260, y = cy + (Math.random() - 0.5) * 140;
            ctx.beginPath(); ctx.arc(x, y, 1, 0, Math.PI * 2); ctx.fill();
          }
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${STAGES[stage].desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initMeltingPointLab() {
      const canvas = document.getElementById('melting-point-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-melting-point');
      const obs = document.getElementById('melting-point-obs');
      const DATA = {
        ice: { mp: 0, strength: 'Weak', color: '#60a5fa' },
        urea: { mp: 133, strength: 'Moderate', color: '#f59e0b' },
        iron: { mp: 1538, strength: 'Very strong', color: '#ef4444' }
      };
      const MAXMP = 1538;

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const d = DATA[sel.value];

        const barX = 220, barY = 50, barMaxH = 170, barW = 90;
        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 1.5;
        ctx.strokeRect(barX, barY, barW, barMaxH);
        const fillH = Math.max(6, Math.sqrt(d.mp / MAXMP) * barMaxH);
        ctx.fillStyle = d.color;
        ctx.fillRect(barX, barY + barMaxH - fillH, barW, fillH);

        ctx.font = 'bold 16px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(`${sel.options[sel.selectedIndex].text}: ${d.mp}°C`, barX + barW / 2, barY - 15);
        ctx.font = '12px system-ui'; ctx.fillStyle = cssVar('--text-muted');
        ctx.fillText(`Interparticle attraction: ${d.strength}`, barX + barW / 2, barY + barMaxH + 25);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text} melts at ${d.mp}°C.</strong> This reflects ${d.strength.toLowerCase()} interparticle attraction between its particles.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initStatePropertiesLab() {
      const canvas = document.getElementById('state-properties-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-state-properties');
      const obs = document.getElementById('state-properties-obs');
      const INFO = {
        solid: 'Fixed shape AND fixed volume. Particles tightly packed, strong attraction, only vibrate in place.',
        liquid: 'No fixed shape, but fixed volume. Particles close but free to move — takes the shape of its container.',
        gas: 'No fixed shape AND no fixed volume. Particles far apart, negligible attraction, fill all available space.'
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const state = sel.value;
        const cx = W / 2, cy = 150;
        ctx.fillStyle = cssVar('--accent-color');

        if (state === 'solid') {
          for (let r = 0; r < 5; r++) for (let c = 0; c < 6; c++) {
            ctx.beginPath(); ctx.arc(cx - 100 + c * 40, cy - 60 + r * 30, 6, 0, Math.PI * 2); ctx.fill();
          }
        } else if (state === 'liquid') {
          ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2; ctx.strokeRect(cx - 90, cy - 55, 180, 110);
          for (let i = 0; i < 60; i++) {
            const x = cx - 85 + Math.random() * 170, y = cy - 50 + Math.random() * 100;
            ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
          }
        } else {
          for (let i = 0; i < 45; i++) {
            const x = cx - 140 + Math.random() * 280, y = cy - 100 + Math.random() * 200;
            ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI * 2); ctx.fill();
          }
        }

        ctx.font = 'bold 15px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${INFO[state]}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initDiffusionTemperatureLab() {
      const canvas = document.getElementById('diffusion-temp-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-diffusion-temp');
      const obs = document.getElementById('diffusion-temp-obs');
      const SPREAD = { hot: 90, room: 50, cold: 20 };
      const SPEED = { hot: 'fastest', room: 'moderate', cold: 'slowest' };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const spread = SPREAD[sel.value];
        const cx = W / 2, cy = 150;

        ctx.strokeStyle = cssVar('--border-color'); ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(cx - 70, cy - 80); ctx.lineTo(cx - 70, cy + 80); ctx.lineTo(cx + 70, cy + 80); ctx.lineTo(cx + 70, cy - 80); ctx.stroke();

        const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, spread);
        grad.addColorStop(0, 'rgba(236,72,153,0.9)');
        grad.addColorStop(1, 'rgba(236,72,153,0.05)');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(cx, cy, spread, 0, Math.PI * 2); ctx.fill();

        ctx.fillStyle = '#831843';
        ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2); ctx.fill();

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> Diffusion is ${SPEED[sel.value]} here — higher temperature means faster-moving particles, spreading the pink colour more quickly.`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

    function initMixtureClassifierLab() {
      const canvas = document.getElementById('mixture-classifier-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const sel = document.getElementById('sel-mixture-classifier');
      const obs = document.getElementById('mixture-classifier-obs');
      const DATA = {
        sprout: { uniform: false, desc: 'Green gram, chickpeas, onion, and tomato are all separately visible — a non-uniform mixture.' },
        sugarwater: { uniform: true, desc: 'Sugar particles are evenly distributed and invisible even under a microscope — a uniform mixture.' },
        air: { uniform: true, desc: 'Nitrogen, oxygen, argon, and carbon dioxide are evenly mixed as gases — a uniform mixture.' },
        steel: { uniform: true, desc: 'Iron, nickel, chromium, and carbon are mixed so thoroughly that the alloy looks the same throughout — a uniform mixture.' }
      };

      function draw() {
        const W = canvas.width, H = canvas.height;
        ctx.clearRect(0, 0, W, H);
        const d = DATA[sel.value];
        const cx = W / 2, cy = 150;

        if (d.uniform) {
          for (let i = 0; i < 80; i++) {
            const x = cx - 100 + Math.random() * 200, y = cy - 60 + Math.random() * 120;
            ctx.fillStyle = cssVar('--accent-color'); ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
          }
          ctx.globalAlpha = 1;
        } else {
          const colors = ['#22c55e', '#f59e0b', '#ef4444', '#3b82f6'];
          for (let i = 0; i < 16; i++) {
            const x = cx - 100 + Math.random() * 200, y = cy - 60 + Math.random() * 120;
            ctx.fillStyle = colors[i % 4];
            ctx.beginPath(); ctx.arc(x, y, 10, 0, Math.PI * 2); ctx.fill();
          }
        }

        ctx.font = 'bold 14px system-ui'; ctx.fillStyle = cssVar('--text-normal'); ctx.textAlign = 'center';
        ctx.fillText(sel.options[sel.selectedIndex].text, W / 2, 30);
        ctx.font = 'bold 15px system-ui'; ctx.fillStyle = d.uniform ? '#22c55e' : '#f59e0b';
        ctx.fillText(d.uniform ? 'UNIFORM MIXTURE' : 'NON-UNIFORM MIXTURE', W / 2, 250);

        obs.innerHTML = `<strong>${sel.options[sel.selectedIndex].text}:</strong> ${d.desc}`;
      }

      sel.addEventListener('change', draw);
      draw();
    }

